// The hero: { i, pass, status }. i is the next word to light; words before i are done
// (or missed, on the skipping pass). Timers stop when the tab is hidden and on unmount.
function useRecital() {
    const reduce = typeof window !== 'undefined' && window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    const [st, setSt] = useState(() => (reduce ? { i: WORDS.length, pass: 0, status: { key: 'recited' }, still: true } : { i: 0, pass: 0, status: { key: 'listening' } }));
    const wave = useRef(null);
    useEffect(() => {
        if (reduce) return undefined;
        let i = 0;
        let pass = 0;
        let timer = null;
        let bars = null;
        const skip = () => (pass % 2 === 1 ? SKIP : -1);
        const step = () => {
            const sk = skip();
            let status = null;
            if (i > 0) {
                const a = WORDS[i - 1].ayah;
                if (i === WORDS.length || WORDS[i].ayah !== a) {
                    status = { key: sk >= 0 && WORDS[sk].ayah === a ? 'review' : 'well', n: a + 1 };
                }
            }
            if (i >= WORDS.length) {
                setSt((s) => ({ ...s, i, status: status || s.status }));
                timer = setTimeout(() => { pass += 1; i = 0; setSt({ i: 0, pass, status: { key: 'listening' } }); timer = setTimeout(step, 0); }, 4200);
                return;
            }
            const cur = i;
            setSt((s) => ({ ...s, i: cur, pass, status: status || s.status }));
            i += 1;
            timer = setTimeout(step, cur === sk ? 120 : 560);
        };
        const animateWave = () => {
            const el = wave.current;
            if (!el) return;
            Array.from(el.children).forEach((b, k) => { b.style.height = `${18 + Math.abs(Math.sin(Date.now() / 240 + k * 0.7)) * 70 * Math.random()}%`; });
        };
        const start = () => { if (!timer) timer = setTimeout(step, 0); if (!bars) bars = setInterval(animateWave, 180); };
        const stop = () => { clearTimeout(timer); timer = null; clearInterval(bars); bars = null; };
        // Resuming re-lights the current word (step from i - 1), so a hidden tab never skips one.
        const onVis = () => { if (document.hidden) stop(); else { if (i > 0 && i < WORDS.length) i -= 1; start(); } };
        if (!document.hidden) start();
        document.addEventListener('visibilitychange', onVis);
        return () => { stop(); document.removeEventListener('visibilitychange', onVis); };
    }, [reduce]);
    return [st, wave];
}

function classFor(k, { i, pass, still }) {
    if (still) return 'w done';
    const sk = pass % 2 === 1 ? SKIP : -1;
    if (k < i) return k === sk ? 'w missed' : 'w done';
    if (k === i && k !== sk) return 'w now';
    return 'w';
}

